sketches.source:
setcpm(70/4)

// Water dripping from every direction in a stone hall
drips: s("drip*8?0.6").azimuth(rand.range(-180, 180)).distance(3).seed("dungeon")
  .space("church").gain(rand.range(.06, .16))

// A torch on each wall
torchL: s("fire").slow(4).intensity(.3).density(8).azimuth(-80).distance(2).gain(.14)
torchR: s("fire").slow(4).intensity(.3).density(8).azimuth(80).distance(2).gain(.14)

// Something large breathes as it circles you in the dark, once every sixteen bars
beast: s("engine").slow(8).lpf(250).azimuth(saw.range(-180, 180).slow(16))
  .distance(5).posglide(.5).gain(.12)

// Your own footsteps, just behind you
steps: s("step ~ step ~").azimuth(180).distance(1).lpf(1500).gain(.12)

// irate turns the drone's phase between the ears, a quarter or half a turn a second
drone: note("[d2,a2]").slow(4).s("sawtooth").irate("<.25 .5>")
  .lpf(500).attack(2).sustain(1).release(3).gain(.18)

// A hesitant melody, deep in the stone and centred
melody: n("<[0 ~ 2 ~] [1 ~ ~ -1] [0 ~ 4 3] [2@4]>").scale("D:harmonic minor").transpose(12)
  .s("triangle").timbre("hollow").attack(.05).decay(.8).sustain(.2).release(1)
  .space("church").room(.6).gain(.2)

setcpm(100/4)

// The same noise feeds both ears, but one ear's noise is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear the jingle: C, Dm, Em, C
secret: s("white*4").dichotic("<[523 659 784 1047] [587 698 880 1175] [659 784 988 1319] [1047@4]>")
  .dichoticq(30).attack(.01).sustain(1).release(.05).gain(.16)

// A quiet hint: the first bar on a chip pulse, once every four bars
hint: note("<[c5 e5 g5 c6] ~ ~ ~>").s("square").pw(.25)
  .decay(.1).sustain(.3).release(.05).gain(.07)

// Treasure sparkles placed around you, a little above
sparkle: n(irand(8).segment(8)).scale("C:major pentatonic").transpose(24)
  .degradeBy(.6).seed("treasure")
  .s("triangle").timbre("glass").decay(.15).sustain(0)
  .azimuth(rand.range(-150, 150)).elevation(30).distance(2).gain(.08)

// A soft pad holding the chords
pad: note("<[c3,e3,g3] [d3,f3,a3] [e3,g3,b3] [c3,e3,g3]>").s("sawtooth").unison(3).detune(.2)
  .attack(.5).sustain(.8).release(1).lpf(1200).room(.6).gain(.1)
